const QUEST_RUNTIME_KEY = Symbol.for("jshack:quests:runtime:installed");
const QUEST_EVENT_ROUTES_KEY = Symbol.for("jshack:quests:runtime:eventRoutes");
const QUEST_SCRIPT_ID = "quest.runtime";
